package com.bank.topn.service;

import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Finds the K largest amounts using a size-K min-heap.
public class TopTransactionsService {
    private static final Logger log = Logger.getLogger(TopTransactionsService.class.getName());

    public List<Integer> topK(int[] amounts, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>(); // natural order = min-heap
        for (int i = 0; i < k; i++) minHeap.offer(amounts[i]);  // seed with first K
        for (int i = k; i < amounts.length; i++) {
            if (amounts[i] > minHeap.peek()) {                   // beats the weakest kept
                minHeap.poll();
                minHeap.offer(amounts[i]);
            }
        }
        List<Integer> result = new ArrayList<>(minHeap);
        log.info(() -> "Top " + k + " amounts = " + result);
        return result;
    }
}
